'use strict';

import fs from 'node:fs';

const input = process.argv[2];
const expected = { name: 'release-notes', version: '1.2.3', files: 3 };

function fail(message, exitCode) {
  console.log(message);
  process.exit(exitCode);
}

if (!input) {
  fail('FAIL missing input: <none>', 2);
}

let text;
try {
  text = fs.readFileSync(input, 'utf8');
} catch (error) {
  if (error && error.code === 'ENOENT') {
    fail(`FAIL missing input: ${input}`, 2);
  }
  fail(`FAIL unreadable input: ${input}`, 2);
}

let value;
try {
  value = JSON.parse(text);
} catch {
  fail(`FAIL invalid input: malformed JSON: ${input}`, 4);
}

if (value === null || typeof value !== 'object' || Array.isArray(value)) {
  fail(`FAIL invalid input: expected object: ${input}`, 4);
}

for (const field of ['name', 'version', 'files']) {
  if (!Object.prototype.hasOwnProperty.call(value, field)) {
    fail(`FAIL invalid input: missing field: ${field}`, 4);
  }
}

if (typeof value.name !== 'string') {
  fail('FAIL invalid input: field name must be string', 4);
}
if (typeof value.version !== 'string') {
  fail('FAIL invalid input: field version must be string', 4);
}
if (typeof value.files !== 'number' || !Number.isInteger(value.files)) {
  fail('FAIL invalid input: field files must be integer', 4);
}

if (value.name !== expected.name) {
  fail(`FAIL changed input: name expected ${expected.name} got ${value.name}`, 3);
}
if (value.version !== expected.version) {
  fail(`FAIL changed input: version expected ${expected.version} got ${value.version}`, 3);
}
if (value.files !== expected.files) {
  fail(`FAIL changed input: files expected ${expected.files} got ${value.files}`, 3);
}

console.log(`PASS input=${input} version=${value.version} files=${value.files}`);

