import { spawnSync } from 'node:child_process';

const program = process.argv[2] || 'starter.mjs';
const checks = [
  {
    label: 'positive',
    fixture: 'release.json',
    exit: 0,
    output: 'PASS input=release.json version=1.2.3 files=3'
  },
  {
    label: 'changed',
    fixture: 'changed.json',
    exit: 3,
    output: 'FAIL changed input: version expected 1.2.3 got 1.2.4'
  }
];

for (const check of checks) {
  const result = spawnSync(process.execPath, [program, check.fixture], {
    encoding: 'utf8'
  });
  const actualOutput = result.stdout.trim();
  if (result.status !== check.exit || actualOutput !== check.output || result.stderr !== '') {
    console.log(`FAIL ${check.label} check`);
    console.log(`EXPECTED EXIT: ${check.exit}`);
    console.log(`ACTUAL EXIT: ${result.status}`);
    console.log(`EXPECTED OUTPUT: ${check.output}`);
    console.log(`ACTUAL OUTPUT: ${actualOutput}`);
    if (result.stderr !== '') console.log(`UNEXPECTED STDERR: ${result.stderr.trim()}`);
    process.exit(1);
  }
  console.log(`PASS ${check.label} check`);
}

